#' @export
LSDTTest <- function(
    data,
    mi,
    ni,
    mj,
    nj,
    ve,
    mse,
    a = "0.0250") {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("LSDTTest requires jmvcore to be installed (restart may be required)")

    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame())


    options <- LSDTTestOptions$new(
        mi = mi,
        ni = ni,
        mj = mj,
        nj = nj,
        ve = ve,
        mse = mse,
        a = a)

    analysis <- LSDTTestClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

